 @property({attribute:false}) hass?:Hass;@state() private machineState:MachineState='IDLE';@state() private muted=true;private config!:CardConfig;private runtime?:ReturnType<typeof runtimeFor>;private unsubscribe?:()=>void;private camera?:any;private portal?:HTMLDivElement;private cameraSignature='';private currentBrightness=100;private currentVolume=100;
