 static getConfigElement(){return document.createElement('baby-monitor-kiosk-card-editor')} static getStubConfig(){return{type:'custom:baby-monitor-kiosk-card',camera:'camera.babykamer',sound_sensor:'binary_sensor.babykamer_geluid',preload:true,silence_duration:5,kiosk:{device_bound:true}}}
