import type {CardConfig,Hass,MachineState} from './types';import {defaults} from './types';import {BabyMonitorMachine} from './machine';
type Listener=(s:MachineState)=>void;
class Runtime {machine:BabyMonitorMachine;listeners=new Set<Listener>();lastLoud=false;state:MachineState='IDLE';
 constructor(public config:CardConfig,private key:string){this.machine=new BabyMonitorMachine((config.trigger_for??defaults.trigger_for)*1000,(config.silence_duration??defaults.silence_duration)*1000,(config.manual_close_cooldown??defaults.manual_close_cooldown)*1000,s=>{this.state=s;this.listeners.forEach(x=>x(s));if(s==='IDLE'&&this.lastLoud)queueMicrotask(()=>this.machine.dispatch({type:'LOUD'}))})}
 update(hass:Hass){const e=hass.states[this.config.sound_sensor];if(!e)return;const numeric=!this.config.sound_sensor.startsWith('binary_sensor.');const value=Number(e.state);if(numeric&&!Number.isFinite(value))return;let loud;if(numeric){loud=this.lastLoud?value>(this.config.sound_reset_db??defaults.sound_reset_db):value>=(this.config.sound_threshold_db??defaults.sound_threshold_db)}else{if(!['on','off'].includes(e.state))return;loud=e.state==='on'}if(loud!==this.lastLoud){this.lastLoud=loud;this.machine.dispatch({type:loud?'LOUD':'QUIET'})}}
 subscribe(l:Listener){this.listeners.add(l);l(this.state);return()=>{this.listeners.delete(l);if(!this.listeners.size){this.machine.destroy();if(runtimes.get(this.key)===this)runtimes.delete(this.key)}}} close(){this.machine.dispatch({type:'MANUAL_CLOSE'})} remainingMs(){return this.machine.remainingMs()}}
const runtimes=new Map<string,Runtime>();const signatures=new Map<string,string>();export function runtimeFor(c:CardConfig){const id=c.id??`${c.camera??c.stream}|${c.sound_sensor}`;const signature=JSON.stringify([c.sound_sensor,c.sound_threshold_db,c.sound_reset_db,c.trigger_for,c.silence_duration,c.manual_close_cooldown]);let r=runtimes.get(id);if(!r||signatures.get(id)!==signature){r=new Runtime(c,id);runtimes.set(id,r);signatures.set(id,signature)}return r}
const owners=new Map<string,unknown>();export function claimOwner(id:string,owner:unknown){if(!owners.has(id))owners.set(id,owner);return owners.get(id)===owner}export function releaseOwner(id:string,owner:unknown){if(owners.get(id)===owner)owners.delete(id)}
